std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

// Iterate through all vertices in the regular triangulation
for (RT::Finite_vertices_iterator it = rt.finite_vertices_begin();
     it != rt.finite_vertices_end(); ++it) {

    // Get the vertex position
    Point p = it->point();

    // Get the velocity (using the velocity function from context)
    Vector v = velocity(it->cell());

    // Get the mass (from the potential value stored in the vertex)
    double mass = it->point().z(); // Assuming z-coordinate stores mass/potential

    // Count the number of edges connected to this vertex
    int edge_count = 0;
    for (RT::Vertex_circulator circ = it->vertex_circulator();
         circ != 0 && circ != it->vertex_circulator(); ++circ) {
        if (is_small_edge(rt, circ->edge(), threshold)) {
            edge_count++;
        }
    }

    // Classify the node type
    NodeType type = type_from_edge_count(edge_count);

    // Create and add the node
    nodes.emplace_back(p, v, mass, type);
}

return nodes;

